pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val, uint256 _val2) internal {
        vm.assume(true);
        try c.SetMinSum(_val) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(_val2) {} catch { return; }
        assertTrue(c.MinSum() == _val);
    }

    function testFuzz_run(uint256 _val, uint256 _val2) public {
        _run(_val, _val2);
    }

    receive() external payable {}
}
